-- Daikin HVAC Installation Academy (independent training platform)
-- Portable PostgreSQL schema. IDs are UUID strings generated by the app.
-- Run with: npm run db:migrate

CREATE TABLE IF NOT EXISTS users (
  id uuid PRIMARY KEY,
  email text NOT NULL UNIQUE,
  password_hash text NOT NULL,
  name text NOT NULL,
  role text NOT NULL DEFAULT 'student' CHECK (role IN ('student','instructor','admin')),
  locale text NOT NULL DEFAULT 'en' CHECK (locale IN ('en','ar')),
  company text,
  job_title text,
  country text,
  email_verified_at timestamptz,
  disabled_at timestamptz,
  stripe_customer_id text UNIQUE,
  comp_plan text CHECK (comp_plan IS NULL OR comp_plan IN ('basic','pro')),
  comp_until timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS email_tokens (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  kind text NOT NULL CHECK (kind IN ('verify','reset')),
  token_hash text NOT NULL UNIQUE,
  expires_at timestamptz NOT NULL,
  used_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS sessions (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash text NOT NULL UNIQUE,
  expires_at timestamptz NOT NULL,
  user_agent text,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- ── Technical sources & equipment models ────────────────────────────────
CREATE TABLE IF NOT EXISTS technical_sources (
  id uuid PRIMARY KEY,
  title text NOT NULL,
  doc_type text NOT NULL DEFAULT 'installation_manual',
  manufacturer text NOT NULL DEFAULT 'Daikin',
  revision text,
  reference text,                       -- document number / URL / internal library path
  approved boolean NOT NULL DEFAULT false,
  approved_by uuid REFERENCES users(id),
  approved_at timestamptz,
  rights_note text,                     -- licence / permission to use excerpts
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS equipment_models (
  id uuid PRIMARY KEY,
  category text NOT NULL,
  series text,
  model_number text NOT NULL,
  refrigerant text,
  is_placeholder boolean NOT NULL DEFAULT false,
  verified boolean NOT NULL DEFAULT false,
  source_id uuid REFERENCES technical_sources(id),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS knowledge_chunks (
  id uuid PRIMARY KEY,
  source_id uuid NOT NULL REFERENCES technical_sources(id) ON DELETE CASCADE,
  page_ref text,
  content text NOT NULL,
  model_specific boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- ── Courses ─────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS courses (
  id uuid PRIMARY KEY,
  slug text NOT NULL UNIQUE,
  category text NOT NULL,
  title_en text NOT NULL,
  title_ar text,
  summary_en text NOT NULL DEFAULT '',
  summary_ar text,
  level text NOT NULL DEFAULT 'beginner' CHECK (level IN ('beginner','intermediate','advanced')),
  tier text NOT NULL DEFAULT 'basic' CHECK (tier IN ('basic','pro')),
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','in_review','published','coming_soon')),
  image_url text,
  trailer_key text,                     -- public trailer asset
  is_sample boolean NOT NULL DEFAULT false,
  author_id uuid REFERENCES users(id),
  technical_reviewed_by uuid REFERENCES users(id),
  technical_reviewed_at timestamptz,
  technical_review_notes text,
  content_updated_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS course_models (
  course_id uuid NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
  model_id uuid NOT NULL REFERENCES equipment_models(id) ON DELETE CASCADE,
  PRIMARY KEY (course_id, model_id)
);

CREATE TABLE IF NOT EXISTS chapters (
  id uuid PRIMARY KEY,
  course_id uuid NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
  position int NOT NULL DEFAULT 0,
  title_en text NOT NULL,
  title_ar text
);

CREATE TABLE IF NOT EXISTS lessons (
  id uuid PRIMARY KEY,
  course_id uuid NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
  chapter_id uuid NOT NULL REFERENCES chapters(id) ON DELETE CASCADE,
  position int NOT NULL DEFAULT 0,
  title_en text NOT NULL,
  title_ar text,
  body_en text NOT NULL DEFAULT '',     -- lightweight markdown subset
  body_ar text,
  duration_min int NOT NULL DEFAULT 5,
  is_free_preview boolean NOT NULL DEFAULT false,
  tier text NOT NULL DEFAULT 'basic' CHECK (tier IN ('basic','pro')),
  spec_status text NOT NULL DEFAULT 'generic' CHECK (spec_status IN ('generic','model_specific')),
  video_key text,                       -- private asset key (NULL = not uploaded)
  flow jsonb,                           -- installation flowchart steps
  diagram jsonb,                        -- labeled diagram definition
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS lesson_sources (
  lesson_id uuid NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
  source_id uuid NOT NULL REFERENCES technical_sources(id) ON DELETE CASCADE,
  page_ref text,
  PRIMARY KEY (lesson_id, source_id)
);

-- Model-specific values. Shown only when verified + approved source + model + page ref.
CREATE TABLE IF NOT EXISTS lesson_specs (
  id uuid PRIMARY KEY,
  lesson_id uuid NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
  label text NOT NULL,
  value text,
  unit text,
  condition_note text,
  model_id uuid REFERENCES equipment_models(id),
  source_id uuid REFERENCES technical_sources(id),
  page_ref text,
  verified boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS lesson_subtitles (
  lesson_id uuid NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
  lang text NOT NULL CHECK (lang IN ('en','ar')),
  storage_key text NOT NULL,
  PRIMARY KEY (lesson_id, lang)
);

CREATE TABLE IF NOT EXISTS resources (
  id uuid PRIMARY KEY,
  course_id uuid NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
  title_en text NOT NULL,
  title_ar text,
  kind text NOT NULL DEFAULT 'checklist' CHECK (kind IN ('checklist','template','reference')),
  storage_key text,                     -- private asset (uploaded file)
  inline_markdown text,                 -- or inline content rendered as printable page
  created_at timestamptz NOT NULL DEFAULT now()
);

-- ── Assessments ─────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS quizzes (
  id uuid PRIMARY KEY,
  course_id uuid NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
  lesson_id uuid REFERENCES lessons(id) ON DELETE SET NULL,
  kind text NOT NULL DEFAULT 'lesson' CHECK (kind IN ('lesson','final')),
  title_en text NOT NULL,
  title_ar text,
  pass_mark int NOT NULL DEFAULT 80 CHECK (pass_mark BETWEEN 1 AND 100)
);

CREATE TABLE IF NOT EXISTS quiz_questions (
  id uuid PRIMARY KEY,
  quiz_id uuid NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,
  position int NOT NULL DEFAULT 0,
  prompt_en text NOT NULL,
  prompt_ar text,
  options_en jsonb NOT NULL,
  options_ar jsonb,
  correct_index int NOT NULL,
  explanation_en text,
  explanation_ar text
);

CREATE TABLE IF NOT EXISTS quiz_attempts (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  quiz_id uuid NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,
  score_pct int NOT NULL,
  passed boolean NOT NULL,
  answers jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- ── Learner state ───────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS enrollments (
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  course_id uuid NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  last_activity_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, course_id)
);

CREATE TABLE IF NOT EXISTS lesson_progress (
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  lesson_id uuid NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
  completed_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, lesson_id)
);

CREATE TABLE IF NOT EXISTS saved_lessons (
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  lesson_id uuid NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, lesson_id)
);

CREATE TABLE IF NOT EXISTS certificates (
  id uuid PRIMARY KEY,
  number text NOT NULL UNIQUE,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  course_id uuid NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
  score_pct int NOT NULL,
  issued_at timestamptz NOT NULL DEFAULT now(),
  revoked_at timestamptz,
  UNIQUE (user_id, course_id)
);

CREATE TABLE IF NOT EXISTS reviews (
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  course_id uuid NOT NULL REFERENCES courses(id) ON DELETE CASCADE,
  rating int NOT NULL CHECK (rating BETWEEN 1 AND 5),
  comment text,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, course_id)
);

-- ── Billing ─────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS plans (
  id uuid PRIMARY KEY,
  code text NOT NULL CHECK (code IN ('basic','pro')),
  interval text NOT NULL CHECK (interval IN ('month','year')),
  name text NOT NULL,
  price_usd_cents int NOT NULL CHECK (price_usd_cents >= 0),
  active boolean NOT NULL DEFAULT true,
  stripe_price_id text,
  UNIQUE (code, interval)
);

CREATE TABLE IF NOT EXISTS subscriptions (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  stripe_subscription_id text NOT NULL UNIQUE,
  plan_code text NOT NULL CHECK (plan_code IN ('basic','pro')),
  interval text NOT NULL DEFAULT 'month',
  status text NOT NULL,
  current_period_end timestamptz,
  cancel_at_period_end boolean NOT NULL DEFAULT false,
  pending_plan_code text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS payments (
  id uuid PRIMARY KEY,
  user_id uuid REFERENCES users(id) ON DELETE SET NULL,
  stripe_invoice_id text NOT NULL UNIQUE,
  amount_cents int NOT NULL,
  currency text NOT NULL DEFAULT 'usd',
  status text NOT NULL CHECK (status IN ('paid','failed','refunded')),
  hosted_invoice_url text,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS stripe_events (
  id text PRIMARY KEY,
  type text NOT NULL,
  processed_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS promo_codes (
  id uuid PRIMARY KEY,
  code text NOT NULL UNIQUE,
  percent_off int CHECK (percent_off IS NULL OR percent_off BETWEEN 1 AND 100),
  amount_off_cents int CHECK (amount_off_cents IS NULL OR amount_off_cents > 0),
  max_redemptions int,
  expires_at timestamptz,
  active boolean NOT NULL DEFAULT true,
  stripe_coupon_id text,
  stripe_promotion_code_id text,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS settings (
  key text PRIMARY KEY,
  value jsonb NOT NULL
);

CREATE TABLE IF NOT EXISTS audit_log (
  id uuid PRIMARY KEY,
  actor_id uuid,
  action text NOT NULL,
  entity text,
  details jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_lessons_course ON lessons(course_id, position);
CREATE INDEX IF NOT EXISTS idx_progress_user ON lesson_progress(user_id);
CREATE INDEX IF NOT EXISTS idx_attempts_user ON quiz_attempts(user_id, quiz_id);
CREATE INDEX IF NOT EXISTS idx_subs_user ON subscriptions(user_id);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_models_number ON equipment_models(model_number);
